import{_ as s,o as e,c as i,ag as n}from"./chunks/framework.D9ghT4bC.js";const h=JSON.parse('{"title":"Unciv Lua API 扩展（VSCode）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/Modders/Lua-API-Extension.md","filePath":"zh/Modders/Lua-API-Extension.md"}'),o={name:"zh/Modders/Lua-API-Extension.md"};function l(t,a,r,c,d,p){return e(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="unciv-lua-api-扩展-vscode" tabindex="-1">Unciv Lua API 扩展（VSCode） <a class="header-anchor" href="#unciv-lua-api-扩展-vscode" aria-label="Permalink to &quot;Unciv Lua API 扩展（VSCode）&quot;">​</a></h1><p><strong>一次安装，补全永不过期。</strong> <code>unciv-lua-api</code> VSCode 扩展是一个云端薄拉取器：每次启动 VSCode（或打开 <code>.lua</code> 文件）都会从 UncivCN 文档站拉取最新的 <code>lua-api.lua</code> / <code>lua-map-api.lua</code> 并同步到 <code>~/.unciv/lua-api/</code>。配合 LuaLS 语言服务器，<code>ctx.…</code> 的自动补全、悬停说明与拼写检查<strong>永不落后</strong>——无需手动下载、无需复制文件、无需检查更新。</p><h2 id="为什么需要它" tabindex="-1">为什么需要它 <a class="header-anchor" href="#为什么需要它" aria-label="Permalink to &quot;为什么需要它&quot;">​</a></h2><p>Lua API 定义文件（<code>lua-api.lua</code> / <code>lua-map-api.lua</code>，由游戏代码生成）会随每次发版变化。手工把定义复制进模组意味着：</p><ul><li>忘记检查新版本 → 补全过期、提示错误；</li><li>每个模组都要一份副本，需反复重新同步；</li><li>新 API（如 <code>civ.discoverTech()</code>）在你想起更新之前永远不补全。</li></ul><p>扩展通过<strong>数据与逻辑解耦</strong>解决这个问题：定义文件放在云端（每次发版自动部署），扩展只负责拉取。扩展本体几乎永远不需要更新。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ol><li><strong>安装 Lua 语言服务器</strong>：在 VSCode 中安装 <strong>Lua</strong> 扩展（作者 sumneko，即 LuaLS 语言服务器）</li><li><strong>安装 Unciv Lua API 扩展</strong>：从最新的 <a href="https://github.com/AutumnPizazz/Unciv/releases" target="_blank" rel="noreferrer">UncivCN Release</a> 下载 <code>unciv-lua-api.vsix</code>（每个 Release 都附带，约 6 KB），然后在 VSCode 中执行 <strong>扩展 → ⋯ → 从 VSIX 安装…</strong> 选择该文件</li><li><strong>一键配置</strong>：打开命令面板（Ctrl+Shift+P），运行 <strong>Unciv: Configure Lua API autocompletion</strong>。它会将 <code>~/.unciv/lua-api</code>（绝对路径）加入你的用户级 <code>Lua.workspace.library</code> 设置——对<strong>本机所有模组工作区</strong>生效，只需做这一次</li></ol><p>完成。打开任意模组目录开始写：<code>ctx.</code> 自动补全，悬停 <code>ctx.civ.addGold(</code> 显示签名，<code>ctx.civ.addGoldd(...)</code> 这类拼写错误即时红色波浪线。地图脚本（<code>GenerateMap(ctx)</code>）同样受益于 <code>lua-map-api.lua</code>——两个文件都由扩展自动管理。</p><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>游戏代码 → 生成 lua-api.lua / lua-map-api.lua（头部带 -- Unciv version: 标记）</span></span>
<span class="line"><span>    ↓ 每次发版自动部署</span></span>
<span class="line"><span>文档站：https://club.unciv.cn/Unciv/Modders/lua-api.lua</span></span>
<span class="line"><span>    ↓ 每次 VSCode 启动 / 打开 .lua 文件时拉取（备用源 GitHub raw 自动切换）</span></span>
<span class="line"><span>扩展 → ~/.unciv/lua-api/</span></span>
<span class="line"><span>    ↓ 一键配置</span></span>
<span class="line"><span>LuaLS workspace.library（用户级设置）→ 所有模组自动补全</span></span></code></pre></div><ul><li><strong>更新判断</strong>：生成文件头部带 <code>-- Unciv version: 4.21.6.6 (build 1250)</code> 标记，新旧版本一目了然；扩展仅在内容真正变化时写盘</li><li><strong>离线可用</strong>：云端不可达时保留上次同步的副本（带版本头），补全照常工作，联网后下次启动自动追平</li><li><strong>手动刷新</strong>：命令面板 → <strong>Unciv: Update Lua API definitions now</strong></li></ul><h2 id="手动配置-备选" tabindex="-1">手动配置（备选） <a class="header-anchor" href="#手动配置-备选" aria-label="Permalink to &quot;手动配置（备选）&quot;">​</a></h2><p>不想用扩展的话，把定义文件从仓库 <code>docs/Modders/</code>（或<a href="https://club.unciv.cn/Unciv/Modders/lua-api.lua" target="_blank" rel="noreferrer">文档站</a>）复制进模组，并创建 <code>.luarc.json</code>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;runtime.version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Lua 5.2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;workspace.library&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;.lua-api&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;diagnostics.globals&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ctx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>记得每次游戏更新后重新复制——这正是扩展帮你消灭的麻烦。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>需要游戏或源码吗？</strong> 不需要。只需 VSCode + Lua 语言服务器 + 本扩展。</p><p><strong>为什么不在 VSCode 市场里？</strong> 扩展刻意做成薄拉取器——定义文件实时来自云端，不依赖市场推送也能保持最新。将来如需上架（Open VSX / VSCode Marketplace），CI 加一步发布即可，扩展本体无需改动。</p><p><strong>用 VSCodium / Cursor 等其他编辑器？</strong> 扩展走 VSCode 扩展 API；其他编辑器可手动把 LuaLS 的 <code>workspace.library</code> 指向 <code>~/.unciv/lua-api</code>（先在 VSCode 里跑一次扩展，或手动同步文件）。</p><p><strong>定义文件从哪来？</strong> 由游戏代码生成（<code>LuaApiDocs</code> / <code>LuaMapGenApiDocs</code> 数据表，见<a href="./../UncivCN/Coding-standards.html">代码规范</a>）——与<a href="./Lua-API-Reference.html">Lua API 参考</a>同源，网站上看到的文档和编辑器里的定义永远不会不一致。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./Lua-Modding.html">Lua 脚本</a> —— 教程、触发方式与生命周期钩子</li><li><a href="./Lua-API-Reference.html">Lua API 参考</a> —— 上下文表的全部函数与属性</li><li><a href="./Lua-Map-API-Reference.html">Lua 地图脚本 API 参考</a> —— 地图脚本专用的生成期 API</li></ul>`,23)])])}const g=s(o,[["render",l]]);export{h as __pageData,g as default};
